import { z } from 'zod';
import type {
  ProfileReference,
  ProfileUsage,
} from '../../types/design-profile';

export interface AnalysisInput {
  reference: ProfileReference;
  images: string[];
}
const MAX_REFERENCES = 4;
const MAX_IMAGES = 20;
const MAX_BYTES = 20 * 1024 * 1024;
const MAX_TEXT_CHARACTERS = 16_000;
const descriptionSchema = {
  type: 'object',
  properties: { description: { type: 'string' } },
  required: ['description'],
  additionalProperties: false,
};
const observationsSchema = {
  type: 'object',
  properties: {
    observations: {
      type: 'array',
      items: {
        type: 'object',
        properties: { id: { type: 'string' }, description: { type: 'string' } },
        required: ['id', 'description'],
        additionalProperties: false,
      },
    },
  },
  required: ['observations'],
  additionalProperties: false,
};
const description = z.object({
  description: z.string().trim().min(1).max(8000),
});

export const fitsAnalysisBatch = (references: ProfileReference[]): boolean =>
  references.length <= MAX_REFERENCES &&
  references.reduce((sum, item) => sum + item.media.length, 0) <= MAX_IMAGES &&
  references.reduce((sum, item) => sum + item.text.length, 0) <=
    MAX_TEXT_CHARACTERS &&
  references.reduce(
    (sum, item) =>
      sum + item.media.reduce((bytes, media) => bytes + media.bytes, 0),
    0,
  ) <= MAX_BYTES;

export const prepareAnalysisBatch = (inputs: AnalysisInput[]) => {
  const images = inputs.flatMap((input) => input.images);
  const instruction =
    'Describe the visible design of this reference in at most 100 words: layout, typography, color, material, and specific controls or imagery. Ground every claim in the actual image or supplied text. This is an observation, not a confirmed user preference.';
  if (inputs.length === 1)
    return {
      images,
      schema: descriptionSchema,
      prompt: `${instruction} Reference text: ${inputs[0].reference.text}`,
    };
  let offset = 0;
  const references = inputs.map(({ reference, images: paths }) => {
    const imageIndexes = paths.map((_, index) => offset + index);
    offset += paths.length;
    return { id: reference.id, text: reference.text, imageIndexes };
  });
  return {
    images,
    schema: observationsSchema,
    prompt: `Analyze each reference independently. For each reference: ${instruction} Return one observation per reference ID. Do not transfer details between references. imageIndexes are zero-based positions in the Reference files array; inspect only those images for that reference. When imageIndexes is empty, summarize only the supplied text and state that visual styling is unavailable; do not infer alignment, layout, typography, colors, materials, controls, or imagery. References: ${JSON.stringify(references)}`,
  };
};

export const analysisDescription = ({
  value,
  referenceId,
  count,
}: {
  value: unknown;
  referenceId: string;
  count: number;
}): string => {
  if (count === 1) return description.parse(value).description;
  const { observations } = z
    .object({ observations: z.array(z.unknown()) })
    .parse(value);
  const matches = observations.filter(
    (item) => z.object({ id: z.literal(referenceId) }).safeParse(item).success,
  );
  if (matches.length !== 1)
    throw new Error(
      'Reference analysis must contain exactly one result for its ID',
    );
  return description.parse(matches[0]).description;
};

export const analysisUsage = (
  usage: ProfileUsage,
  count: number,
): ProfileUsage => {
  if (count === 1) return usage;
  const share = (tokens: number | undefined) =>
    tokens === undefined ? undefined : tokens / count;
  return {
    inputTokens: share(usage.inputTokens),
    outputTokens: share(usage.outputTokens),
    cachedInputTokens: share(usage.cachedInputTokens),
    allocation: 'equal-share',
  };
};
